/// <summary>
/// The <c>METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController</c> class for the subtask to delete rejected free text invoices.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
public class METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Runs the class with the specified arguments.
/// </summary>
/// <param name="_args">The arguments passed to the subtask.</param>
public static void main(Args _args)
{
    METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController controller = new METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController();
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions.
/// </summary>
/// <returns>
/// <c>true</c> if the batch task is retryable; otherwise, <c>false</c>.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Creates a new instance of the <c>METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController</c> class from arguments.
/// </summary>
/// <returns>A new instance of the <c>METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController</c> class.</returns>
public static METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController newFromArgs()
{
    identifierName            className     = classStr(METBulkFreeTextInvoiceWorkflowSubmissionSubTaskService);
    identifierName            methodName    = methodStr(METBulkFreeTextInvoiceWorkflowSubmissionSubTaskService, processOperation);
    SysOperationExecutionMode executionMode = SysOperationExecutionMode::Synchronous;

    METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController controller = new METBulkFreeTextInvoiceWorkflowSubmissionSubTaskController(className, methodName, executionMode);

    return controller;
}
